message.content:
{
  "candidate_edge_types": [
    {
      "name": "LIVENESS_EVIDENCE_JUSTIFIES_CONTINUED_WAITING",
      "definition": "An observation confirming that a previously launched long-running process is still alive and actively consuming resources is used to justify a decision to keep waiting and monitoring it instead of restarting, aborting, or intervening.",
      "source_description": "An observation that verifies the continued liveness/activity of an earlier launched long-running process (e.g., process status showing active CPU usage).",
      "target_description": "A subsequent agent decision or plan to continue waiting and polling rather than restart or abort the process."
    },
    {
      "name": "UNCHANGED_STATE_TRIGGERS_REPEATED_POLL",
      "definition": "An observation that reports the same execution state as the previously observed state, showing no new progress, leads the agent to re-execute the same monitoring action.",
      "source_description": "An observation of a long-running task whose reported state is identical to the prior observation (no new milestone or output).",
      "target_description": "A repeated monitoring/polling action of the same kind directed at the same resource."
    },
    {
      "name": "OBSERVED_MILESTONE_UPDATES_PROGRESS_ESTIMATE",
      "definition": "A newly observed progress milestone in a long-running task is used to refine the agent's estimate of the processing rate and the remaining time/completion point, which shapes the plan for subsequent monitoring.",
      "source_description": "An observation that reports a new progress milestone (e.g., an iteration counter value reached) along with a timestamp.",
      "target_description": "A revised progress/timing assessment and corresponding monitoring plan derived from that milestone."
    },
    {
      "name": "METRIC_IMPROVEMENT_CONFIRMS_TASK_HEALTH",
      "definition": "An observed improvement in a monitored quality metric is interpreted as evidence that the running task is behaving correctly, supporting a decision that no corrective action is needed.",
      "source_description": "An observation of a monitored metric value that has improved relative to an earlier observation of the same metric.",
      "target_description": "An agent assessment that the task is progressing correctly and does not require repair or intervention."
    }
  ]
}

